#[cfg(test)]
mod compact_miri {
    use super::*;
    #[test]
    fn pcm_transition_and_rejection_boundaries() {
        for len in [0usize, 1, 7, 8, 9, 255, 256, 257, 264, 265, 272, 273] {
            let mut frames = vec![i16::MAX; len];
            let pattern = vec![i16::MIN; len];
            frames[..len.min(256)].fill(30_720);
            for best in [0.0, I16_SCALE, 496.0 - I16_SCALE, 496.0, 496.0 + I16_SCALE, 512.0, 512.0 + 2.0 * I16_SCALE, f32::INFINITY] {
                let mut expected=0.0f32;
                for (index, (&a,&b)) in frames.iter().zip(&pattern).enumerate() {
                    expected += (f32::from(a) * I16_SCALE - f32::from(b) * I16_SCALE).abs();
                    if (index + 1) % 8 == 0 && expected >= best { break; }
                }
                assert_eq!(correlation_score(&frames,&pattern,best).to_bits(),expected.to_bits(),"len={len} best={best}");
            }
        }
    }
}
